using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.JournalEntries;using Namaa.Api.Extensions;using Namaa.Application.JournalEntries.Commands.AddJournalEntryLine;using Namaa.Application.JournalEntries.Commands.CreateJournalEntry;using Namaa.Application.JournalEntries.Commands.PostJournalEntry;using Namaa.Application.JournalEntries.Queries.GetJournalEntryById;using Namaa.Application.JournalEntries.Queries.GetJournalEntries;namespace Namaa.Api.Controllers;[ApiController][Route("api/journal-entries")]public sealed class JournalEntriesController(ISender sender):ControllerBase{[HttpPost]public async Task<IActionResult>Create(CreateJournalEntryRequest request,CancellationToken cancellationToken){var result=await sender.Send(new CreateJournalEntryCommand(request.EntryNumber,request.EntryDate,request.CreatedByUserId,request.Description,request.SourceType,request.SourceId),cancellationToken);return result.IsFailure?result.ToActionResult(this):CreatedAtAction(nameof(GetById),new{id=result.Value.Id},result.Value);}[HttpGet]public async Task<IActionResult>GetAll(CancellationToken cancellationToken)=>(await sender.Send(new GetJournalEntriesQuery(),cancellationToken)).ToActionResult(this);[HttpGet("{id:long}")]public async Task<IActionResult>GetById(long id,CancellationToken cancellationToken)=>(await sender.Send(new GetJournalEntryByIdQuery(id),cancellationToken)).ToActionResult(this);[HttpPost("{id:long}/lines")]public async Task<IActionResult>AddLine(long id,AddJournalEntryLineRequest request,CancellationToken cancellationToken)=>(await sender.Send(new AddJournalEntryLineCommand(id,request.AccountId,request.Debit,request.Credit,request.BranchId,request.CostCenterId,request.ProjectId,request.Description),cancellationToken)).ToActionResult(this);[HttpPost("{id:long}/post")]public async Task<IActionResult>Post(long id,PostJournalEntryRequest request,CancellationToken cancellationToken)=>(await sender.Send(new PostJournalEntryCommand(id,request.PostedByUserId,request.PostedAt),cancellationToken)).ToActionResult(this);}
